/** The dev port the localhost fallbacks use when nothing says otherwise. */
export const DEFAULT_CORS_DEV_PORT = 7104

export const AUTO_GENERATED_HEADER =
  '// AUTO-GENERATED by pikku CLI — do not edit'

/**
 * The port of the frontend the localhost fallbacks should name: an explicit
 * `scaffold.cors.port`, else the primary frontend's dev port, else the first
 * frontend that has one, else {@link DEFAULT_CORS_DEV_PORT}.
 */
export const resolveCorsDevPort = (
  explicit: number | undefined,
  frontends:
    Record<string, { primary?: boolean; dev?: { port: number } }> | undefined
): number => {
  if (explicit !== undefined) return explicit
  const withDev = Object.values(frontends ?? {}).filter((f) => f.dev?.port)
  return (
    (withDev.find((f) => f.primary) ?? withDev[0])?.dev?.port ??
    DEFAULT_CORS_DEV_PORT
  )
}

/**
 * The `CORS_ORIGINS` variable and the `allowedOrigins` helper both the CORS
 * middleware and the analytics origin lock read.
 *
 * It sits apart from the middleware file because a file holding a zod schema
 * may not also make wiring calls (PKU490): the CLI imports schema files at
 * runtime, and the wiring side effects crash without a server. `defineVariable`
 * is not wiring, so the helper may share this file.
 *
 * The helper reads the `variables` service, never `process.env`: a deployed
 * unit is a Cloudflare Worker with no `process.env`, where reading it would
 * silently collapse the allowlist to the localhost fallbacks.
 */
export const serializeCorsOrigins = (
  devPort: number
): string => `${AUTO_GENERATED_HEADER}

import { defineVariable } from '@pikku/core/variable'
import type { VariablesService } from '@pikku/core/services'
import { z } from 'zod'

// The CLI requires \`schema\` to be a named export, not an inline \`z.string()\`.
export const CorsOriginsSchema = z.string()

defineVariable({
  name: 'corsOrigins',
  displayName: 'Allowed Browser Origins',
  description:
    'Comma-separated list of origins allowed to call this API from a browser, e.g. "https://app.example.com". Unset falls back to http://localhost:${devPort} and http://127.0.0.1:${devPort}.',
  variableId: 'CORS_ORIGINS',
  schema: CorsOriginsSchema,
  optional: true,
})

/**
 * The browser origins allowed to call this API: \`CORS_ORIGINS\` as a comma
 * separated list, else the local dev origins on port ${devPort}.
 */
export async function allowedOrigins(
  variables: Pick<VariablesService, 'get'>
): Promise<string[]> {
  const configured = await variables.get<string>('CORS_ORIGINS')
  if (configured) {
    return configured
      .split(',')
      .map((origin) => origin.trim())
      .filter(Boolean)
  }
  return ['http://localhost:${devPort}', 'http://127.0.0.1:${devPort}']
}
`

/**
 * The CORS middleware, registered for every route.
 *
 * \`cors()\` takes a static origin list, so it is built per request: that is what
 * lets the list come from \`variables\` instead of being frozen at import time,
 * before any service exists.
 */
export const serializeCors = (
  leaf: (name: string) => string,
  originsSpecifier: string
): string => `${AUTO_GENERATED_HEADER}

import { addHTTPMiddleware, cors, pikkuMiddleware } from '${leaf('middleware')}'
import { allowedOrigins } from '${originsSpecifier}'

const corsMiddleware = pikkuMiddleware(
  async ({ variables, ...services }, { http, ...wire }, next) => {
    const middleware = cors({
      origin: await allowedOrigins(variables),
      credentials: true,
      headers: ['Content-Type', 'Authorization', 'X-Auth-Return-Redirect'],
    })
    // Both parameters are destructured and reassembled because the inspector
    // fails the build on an undestructured one (PKU410/PKU411).
    await middleware({ variables, ...services }, { http, ...wire }, next)
  }
)

addHTTPMiddleware('*', [corsMiddleware])
`

/**
 * The origin lock on the analytics ingest, built on core's \`requireOrigin\`:
 * exact match on the parsed origin, a missing \`Origin\` refused, a 403
 * \`InvalidOriginError\`. Registered for \`/analytics\` at the default priority,
 * so it runs inside the global CORS middleware and the 403 still carries CORS
 * headers rather than surfacing in the browser as an opaque network error.
 */
export const serializeAnalyticsOrigin = (
  leaf: (name: string) => string,
  originsSpecifier: string,
  globalHTTPPrefix = ''
): string => `${AUTO_GENERATED_HEADER}

import { addHTTPMiddleware, requireOrigin } from '${leaf('middleware')}'
import { allowedOrigins } from '${originsSpecifier}'

// Not what cors() does: cors() sets response headers a browser enforces and a
// non-browser client ignores, whereas this rejects before the function body.
// It stops another site's page from beaconing into this endpoint; it is not
// flood control, because Origin is trusted from nobody but a browser.
addHTTPMiddleware('${globalHTTPPrefix}/analytics', [
  requireOrigin({
    origins: ({ variables }) => allowedOrigins(variables),
  }),
])
`
